import {mkdirSync,writeFileSync} from 'node:fs';
import {createGame,applyAction,legalActions,validateState,exportGame} from '../../dist/js/engine.js';
import {fixture,active,give,placeHero,passWindows,battle} from './advanced.mjs';
const out=process.argv[2]??'/workspace/scratch/burning-banners-interrupts';mkdirSync(out,{recursive:true});
const save=(name,s)=>{const issues=validateState(s);if(issues.length)throw new Error(name+': '+issues.join('; '));writeFileSync(`${out}/${name}.json`,exportGame(s));};
const choose=(s,match)=>{const a=legalActions(s).find(match);if(!a)throw new Error('Missing fixture choice');return applyAction(s,a);};
function extraConfig(k,side='resistance'){const c=fixture();c.scenario.turnOrder.unshift(k);c.scenario.kingdoms.push({id:k,name:k,side,gold:20,income:2});c.unitDefinitions.push({...c.unitDefinitions[0],id:'army-extra',kingdom:k,name:k+' Army'});c.scenario.initialUnits.push({defId:'army-extra',hexId:'D'});return c;}
let s=active();let h=placeHero(s,'hero-fjordland-17','D');h.activated=true;give(s,'player-fjordland','spell-21');s=applyAction(s,{type:'activate',unitId:'unit-1'});s.remainingMP=s.advanced.movement['unit-1']=0;s.moved=true;save('teleport-finished',s);
s=active();h=placeHero(s,'hero-fjordland-17','A','unit-1');give(s,'player-fjordland','treasure-12');battle(s,{hits:2});save('hit-allocation',s);s=applyAction(s,{type:'allocate-hit',unitId:h.id});save('ring-selected-hit',s);
s=active();h=placeHero(s,'hero-fjordland-13','A','unit-1');battle(s,{hits:1});s=applyAction(s,{type:'allocate-hit',unitId:h.id});save('freyja-rescue',s);
s=active();placeHero(s,'hero-orcs-12','C','unit-2');s.units.push({id:`unit-${s.serial++}`,defId:'army-b',kingdom:'orcs',hexId:'E',weakened:false,activated:false});give(s,'player-orcs','treasure-05');s=applyAction(s,{type:'move',unitId:'unit-1',toHex:'B'});save('horn-interception',s);
for(let seed=1;seed<50;seed++){const c=extraConfig('night','invader');c.seed=seed;s=active(c);placeHero(s,'hero-night-12','D','unit-3');const victim=placeHero(s,'hero-fjordland-17','B');s=choose(s,a=>a.cardId==='hero-night-12'&&a.targetId===victim.id);s=passWindows(s);if(s.advanced.pending?.flow==='assassin-failure'){save('luna-failure',s);break;}}
const c=extraConfig('empire');s=active(c);h=placeHero(s,'hero-empire-13','D','unit-3');s.units.find(u=>u.id==='unit-3').hexId=h.hexId='B';s.units.find(u=>u.id==='unit-2').weakened=true;s.units.push({id:`unit-${s.serial++}`,defId:'army-b',kingdom:'orcs',hexId:'E',weakened:true,activated:false});s=applyAction(s,{type:'activate',unitId:'unit-3'});s.pendingCombat={attackerId:'unit-3',targetHex:'C',stage:'ambush',decisionKingdom:'empire'};battle(s,{attacker:'unit-3',defender:'unit-2',targetHex:'C',hits:1,kind:'battle'});s=applyAction(s,{type:'allocate-hit',unitId:'unit-2'});s=passWindows(s);s=applyAction(s,{type:'settlement',choice:'control'});save('sofia-after-advance',s);s=applyAction(s,{type:'magic-choice',value:'stay'});save('sofia-extra-attack',s);
const kc=extraConfig('night','invader');kc.scenario.turnOrder=['fjordland','night','orcs'];kc.hexes.find(h=>h.id==='B').settlement={name:'Coven Town',loyalty:'fjordland',fortified:2,city:false,port:false};s=active(kc);s.covens.push('B');give(s,'player-night','blessing-night-08');s=applyAction(s,{type:'move',unitId:'unit-1',toHex:'B'});save('coven-discovery',s);
console.log('Saved nine validated ordinary import fixtures to '+out);
